function normalAttackReach(){return 105}
function normalAttackArc(){return .2}
// Isometric exploration, navigation and explicit animation/combat state machines.
const TILE=64,MW=57,MH=57,ISOX=.84,ISOY=.46;
let dungeon=null,route=[],moveGoal=null,attackTarget=null,leftDown=false,rightDown=false,playerAction=null,playerAnim=0,playerMoving=false,face=1,revealClock=0,mapOpen=false,seals=0,corpses=[],lootTarget=null,shake=0,hitPause=0,roomTitle='',navClock=0;
const heroSheet=new Image();heroSheet.src='assets/knight-anim.png';const enemySheet=new Image();enemySheet.src='assets/revenant-anim.png';const abilityAtlas=new Image();abilityAtlas.src='assets/ability-atlas.png';
const roomNames=['崩れた玄関','誓いの回廊','灰の書庫','忘れられた納骨堂','沈黙の交差廊','燭火の礼拝堂','地下の貯蔵庫','封印の祭室','黒冠の玉座'];
