function dungeonConnections(random){let candidates=[];for(let id=0;id<9;id++){if(id%3<2)candidates.push([id,id+1]);if(id<6)candidates.push([id,id+3])}for(let i=candidates.length-1;i>0;i--){let j=Math.floor(random()*(i+1));[candidates[i],candidates[j]]=[candidates[j],candidates[i]]}let parent=Array.from({length:9},(_,i)=>i),root=i=>{while(parent[i]!==i)i=parent[i];return i},edges=[],extras=[];for(let [a,b]of candidates){let ra=root(a),rb=root(b);if(ra!==rb){parent[ra]=rb;edges.push([a,b])}else extras.push([a,b])}for(let edge of extras)if(random()<.35)edges.push(edge);return edges}
