function findPath(start,end){if(!end)return[];let a=gridPos(start.x,start.y),b=gridPos(end.x,end.y);if(!isFloor(a.x,a.y)||!isFloor(b.x,b.y))return[];let first=cell(a.x,a.y),goal=cell(b.x,b.y);if(first===goal)return[end];let prev=new Int32Array(MW*MH).fill(-1),q=[first];prev[first]=first;for(let k=0;k<q.length&&prev[goal]<0;k++){let id=q[k],x=id%MW,y=Math.floor(id/MW);for(let [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,ny=y+dy,ni=cell(nx,ny);if(isFloor(nx,ny)&&prev[ni]===-1){prev[ni]=id;q.push(ni)}}}if(prev[goal]<0)return[];let result=[end];for(let at=goal;at!==first;at=prev[at])result.push(center(at%MW,Math.floor(at/MW)));result.reverse();let simple=[],from=start;for(let i=0;i<result.length;){let j=i;while(j+1<result.length&&lineClear(from,result[j+1],15))j++;simple.push(result[j]);from=result[j];i=j+1}return simple}
