function reveal(){dungeon.visible.fill(0);let g=gridPos(p.x,p.y);for(let y=g.y-8;y<=g.y+8;y++)for(let x=g.x-8;x<=g.x+8;x++)if(isFloor(x,y)&&Math.hypot(x-g.x,y-g.y)<8.5&&lineClear(p,center(x,y))){dungeon.visible[cell(x,y)]=1;dungeon.seen[cell(x,y)]=1}let id=dungeon.owner[cell(g.x,g.y)];if(id>=0){let room=dungeon.rooms[id];if(!room.visited){room.visited=true;roomTitle=roomNames[id];say(roomTitle);save()}if(!room.awakened){room.awakened=true;if(id!==0&&id!==8)spawnRoom(room)}if(id===8&&seals===3&&!bossSpawn)awakenBoss()} }
function spawnAt(x,y,boss=false,kind=0){let hp=boss?500+floor*200:48+floor*14;let pos=nearestFloor(x,y);if(!pos)return;enemies.push({...pos,hp,max:hp,boss,kind,t:rand(.2,1),slow:0,anim:rand(0,1),state:'idle',elapsed:0,nav:0,path:[],facing:1,dead:false})}
function spawnRoom(room){for(let i=0;i<5+Math.min(4,floor);i++){let a=rand(0,6.28),r=rand(70,180);let c=center(room.cx,room.cy);spawnAt(c.x+Math.cos(a)*r,c.y+Math.sin(a)*r,false,Math.random()<.28?1:0)}}
function awakenBoss(){bossSpawn=true;let r=dungeon.rooms[8],c=center(r.cx,r.cy);spawnAt(c.x,c.y,true,1);say('黒冠の番人が目覚めた');feed('番人の予備動作を見て回避せよ')}
enterFloor=()=>{p.worldSeed??=Math.floor(Math.random()*1e9);dungeon=makeDungeon(p.worldSeed+floor*7919);p.x=0;p.y=0;p.hp=maxhp();p.mp=100;p.flasks=3;kills=0;seals=0;bossSpawn=false;portal=false;enemies=[];shots=[];drops=[];fx=[];texts=[];props=[];particles=[];zonesFx=[];corpses=[];route=[];moveGoal=null;attackTarget=null;lootTarget=null;playerAction=null;playerAnim=0;held=false;leftDown=false;rightDown=false;cd=Array(8).fill(0);roomTitle=roomNames[0];hudText($('zone'),'深度 '+floor+' / '+zones[(floor-1)%3]);dungeon.rooms[0].visited=true;dungeon.rooms[0].awakened=true;restoreSeals();reveal();say(seals===3?'封印は解放済み。最奥の番人を倒せ':'封印 '+seals+'/3 · 残りの封印を解き、最奥の番人を倒せ');save()};
function pointMove(target){moveGoal=nearestFloor(target.x,target.y);route=findPath(p,moveGoal)}
function selectTarget(){let world=unproject(mouse.x,mouse.y),visible=enemies.filter(e=>e.hp>0&&visibleAt(e.x,e.y));let body=visible.filter(e=>enemyScreenContains(e,mouse.x,mouse.y)).sort((a,b)=>(b.x+b.y)-(a.x+a.y))[0];if(body)return body;let target=visible.sort((a,b)=>dist(a,world)-dist(b,world))[0];return target&&dist(target,world)<Math.max(55,enemyHitRadius(target))?target:null}
canvas.addEventListener('mousedown',e=>{e.stopImmediatePropagation();if(paused||!started)return;if(e.button===0){leftDown=true;attackTarget=selectTarget();let world=unproject(e.clientX,e.clientY);if(e.shiftKey){cast(0);return}let loot=selectGroundDrop(e.clientX,e.clientY,world);if(loot){lootTarget=loot;pointMove(loot);return}if(!attackTarget)pointMove(world);else if(dist(p,attackTarget)>normalAttackReach()-20)pointMove(attackTarget)}if(e.button===2){rightDown=true;cast(1)}},true);
addEventListener('mouseup',()=>{leftDown=false;rightDown=false});addEventListener('blur',()=>{leftDown=false;rightDown=false;route=[];playerAction=null});
