cast=n=>{if(paused||dead||cd[n]>0||playerAction)return;if(n===3){let t=unproject(mouse.x,mouse.y),dx=t.x-p.x,dy=t.y-p.y;let screenDX=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),screenDY=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);if(screenDX||screenDY){dx=screenDX+screenDY;dy=screenDY-screenDX}let len=Math.hypot(dx,dy)||1;for(let i=0;i<18;i++){moveActor(p,dx/len*10,dy/len*10);if(i%3===0)emit(p.x,p.y,3,'#9fbcd4')}p.inv=.3;cd[3]=1.3;route=[];return}if(!skillReady(n)){say(n?'ジェムの装着・マナを確認してください':'');return}let target=attackTarget&&attackTarget.hp>0?{x:attackTarget.x,y:attackTarget.y}:unproject(mouse.x,mouse.y);playerAction={n,target,elapsed:0,impact:n===0?.18:.22,duration:n===0?.46:.48,done:false};playerMoving=false;face=project(target.x,target.y).x<W/2?-1:1};
