const expansionHit=hit;hit=(e,d)=>{if(e.hp<=0)return;expansionHit(e,d);e.flash=.12;if(e.hp<=0){corpses.push({x:e.x,y:e.y,life:7,size:e.boss?110:70,facing:e.facing||1});if(e.boss){portal=true;let c=center(dungeon.rooms[8].cx,dungeon.rooms[8].cy);dungeon.exit=c;say('番人を討伐 · 奥の門から次の深度へ')}}};
interact=()=>{if(paused)return;if(portal&&dungeon.exit&&dist(p,dungeon.exit)<100){floor++;enterFloor();return}let altar=dungeon.altars.find(a=>!a.used&&dist(p,a)<100);if(altar){let danger=enemies.some(e=>e.hp>0&&dist(e,altar)<270);if(danger){say('周囲の敵を倒してから封印を解く');return}altar.used=true;p.expedition.seals.push(altar.room);seals++;p.points++;p.hp=maxhp();feed('封印 '+seals+'/3 · パッシブポイント +1');say('封印が崩れた');burst(altar.x,altar.y,150,'#d5b875');if(seals===3)say('黒冠の玉座への封印が解けた');save();return}let chest=dungeon.chests.find(c=>!c.opened&&dist(p,c)<90);if(chest){chest.opened=true;p.gold+=25+floor*5;drops.push({x:chest.x+20,y:chest.y+15,item:rollItem(randomGearSlot(),true)});feed('古い宝箱を開けた');save();return}let loot=drops.find(d=>dist(p,d)<100);if(loot){if(p.bag.length>=20){say('鞄が満杯です');return}p.bag.push(loot.item);drops.splice(drops.indexOf(loot),1);feed(loot.item.name+' を拾った');save()}};
function animateEnemy(e,dt){e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,e.slow-dt);e.t-=dt;e.nav-=dt;let d=dist(e,p),clear=lineClear(e,p);if(e.state==='attack'){e.elapsed+=dt;if(e.elapsed>=.42&&!e.struck){e.struck=true;if(e.kind){let a=Math.atan2(e.aim.y-e.y,e.aim.x-e.x);for(let j=0;j<(e.boss?5:1);j++){let angle=a+(e.boss?(j-2)*.17:0);shots.push({x:e.x,y:e.y,vx:Math.cos(angle)*220,vy:Math.sin(angle)*220,life:3,damage:e.boss?18+floor*2:9+floor*2,enemy:true})}}else if(dist(e,p)<78&&lineClear(e,p))hurt(7+floor*2);emit(e.x,e.y,5,'#b37d6b')}if(e.elapsed>=.85){e.state='idle';e.t=e.boss?.8:.6}return}if(d>650){e.state='idle';return}let attackRange=e.kind?310:60;if(d<attackRange&&clear&&e.t<=0){e.state='attack';e.elapsed=0;e.struck=false;e.aim={x:p.x,y:p.y};e.facing=project(p.x,p.y).x<project(e.x,e.y).x?-1:1;return}if(e.kind&&d<attackRange&&clear){e.state='idle';return}if(e.nav<=0){e.nav=.6+rand(0,.3);e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p)}let target=e.path?.[0];if(target){let dx=target.x-e.x,dy=target.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let speed=(e.boss?70:87)*(e.slow>0?.35:1)*(e.elite?.includes('swift')?1.4:1),step=Math.min(len,speed*dt);let moved=moveActor(e,dx/len*step,dy/len*step,12);e.state=moved>.1?'walk':'idle';e.facing=(dx-dy)<0?-1:1}}}
update=dt=>{if(paused||!started)return;clock+=dt;notice-=dt;if(notice<=0)hudText($('toast'),'');if(hitPause>0){hitPause-=dt;dt*=.25}cd=cd.map(c=>Math.max(0,c-dt));p.inv=Math.max(0,(p.inv||0)-dt);p.mp=Math.min(100,p.mp+dt*(7+p.focus*2+stat('regen')));playerAnim+=dt;shake=Math.max(0,shake-dt*20);playerMoving=false;
if(playerAction){playerAction.elapsed+=dt;if(playerAction.elapsed>=playerAction.impact&&!playerAction.done){playerAction.done=true;performAction(playerAction)}if(playerAction.elapsed>=playerAction.duration)playerAction=null}else{let dx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),dy=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);let wx=dx+dy,wy=dy-dx;let speed=205*(1+Math.min(.8,stat('speed')/100));if(wx||wy){let len=Math.hypot(wx,wy);playerMoving=moveActor(p,wx/len*speed*dt,wy/len*speed*dt)>.1;face=dx<0?-1:dx>0?1:face}else if(route.length){let target=route[0],vx=target.x-p.x,vy=target.y-p.y,len=Math.hypot(vx,vy);if(len<8)route.shift();else{let step=Math.min(len,speed*dt);playerMoving=moveActor(p,vx/len*step,vy/len*step)>.1;face=(vx-vy)<0?-1:1}}if(attackTarget?.hp>0){if(dist(p,attackTarget)<normalAttackReach()-10+enemyHitRadius(attackTarget)-21&&lineClear(p,attackTarget)){route=[];cast(0)}else if((navClock-=dt)<=0){navClock=.35;pointMove(attackTarget)}}else attackTarget=null;if(leftDown&&keys.Shift)cast(0);if(rightDown)cast(1);if(keys.q)cast(1);if(keys.e)cast(2)}
if(lootTarget&&dist(p,lootTarget)<65){interact();lootTarget=null;route=[]}revealClock-=dt;if(revealClock<=0){revealClock=.14;reveal()}for(let e of enemies)if(e.hp>0){tickAilments(e,dt);if(e.hp>0)animateEnemy(e,dt)};
for(let s of shots)advanceProjectile(s,dt);shots=shots.filter(s=>s.life>0);enemies=enemies.filter(e=>e.hp>0);fx.forEach(f=>f.life-=dt);fx=fx.filter(f=>f.life>0);texts.forEach(t=>{t.life-=dt;t.y-=dt*30});texts=texts.filter(t=>t.life>0);particles.forEach(a=>{a.x+=a.vx*dt;a.y+=a.vy*dt;a.vx*=.96;a.vy*=.96;a.life-=dt});particles=particles.filter(a=>a.life>0);for(let z of zonesFx){z.life-=dt;if(z.kind==='vortex'){z.tick-=dt;if(z.tick<=0){z.tick=.4;for(let e of enemies)if(dist(e,z)<z.r&&lineClear(z,e))spellHit(e,z.damage,z.build);emit(z.x,z.y,5,'#b397e9')}}}zonesFx=zonesFx.filter(z=>z.life>0);corpses.forEach(c=>c.life-=dt);corpses=corpses.filter(c=>c.life>0);if(p.hp<=0){dead=true;paused=true;leftDown=false;rightDown=false;save();$('modal').classList.remove('hidden');$('card').classList.remove('wide');$('card').innerHTML='<label>THE DEPTHS REMEMBER</label><h1>灰に還る</h1><p>装備・成長・解放した封印を保って、この階層を再探索できます。</p><button onclick="dead=false;enterFloor();closePanel()">再挑戦</button>'}};
function diamond(x,y,size=TILE){let s=project(x,y);ctx.beginPath();ctx.moveTo(s.x,s.y-size*ISOY);ctx.lineTo(s.x+size*ISOX,s.y);ctx.lineTo(s.x,s.y+size*ISOY);ctx.lineTo(s.x-size*ISOX,s.y);ctx.closePath()}
function floorTile(gx,gy){let c=center(gx,gy),s=project(c.x,c.y);if(s.x<-100||s.y<-100||s.x>W+100||s.y>H+100)return;ctx.save();ctx.translate(s.x,s.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);if(terrain.complete&&terrain.naturalWidth){let sw=terrain.naturalWidth/14,sh=terrain.naturalHeight/14;ctx.drawImage(terrain,(gx%14)*sw,(gy%14)*sh,sw,sh,-32,-32,64,64)}else{ctx.fillStyle='#333536';ctx.fillRect(-32,-32,64,64)}ctx.strokeStyle='#0005';ctx.lineWidth=1.3;ctx.strokeRect(-32,-32,64,64);if(!dungeon.visible[cell(gx,gy)]){ctx.fillStyle='#000b';ctx.fillRect(-32,-32,64,64)}ctx.restore()}
function wall(gx,gy){let c=center(gx,gy),s=project(c.x,c.y);if(s.x<-110||s.y<-100||s.x>W+110||s.y>H+150)return;let bright=false;for(let [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]])if(isFloor(gx+dx,gy+dy)&&dungeon.visible[cell(gx+dx,gy+dy)])bright=true;ctx.globalAlpha=bright?1:.35;let h=48;ctx.fillStyle='#141c20';ctx.beginPath();ctx.moveTo(s.x-54,s.y);ctx.lineTo(s.x,s.y+29);ctx.lineTo(s.x,s.y+29-h);ctx.lineTo(s.x-54,s.y-h);ctx.closePath();ctx.fill();ctx.fillStyle='#263035';ctx.beginPath();ctx.moveTo(s.x,s.y+29);ctx.lineTo(s.x+54,s.y);ctx.lineTo(s.x+54,s.y-h);ctx.lineTo(s.x,s.y+29-h);ctx.closePath();ctx.fill();ctx.fillStyle='#42484a';ctx.beginPath();ctx.moveTo(s.x,s.y-29-h);ctx.lineTo(s.x+54,s.y-h);ctx.lineTo(s.x,s.y+29-h);ctx.lineTo(s.x-54,s.y-h);ctx.closePath();ctx.fill();ctx.save();ctx.clip();if(terrain.complete&&terrain.naturalWidth){ctx.globalAlpha=bright?.42:.14;let tw=terrain.naturalWidth/8;ctx.drawImage(terrain,(gx%8)*tw,(gy%8)*tw,tw,tw,s.x-54,s.y-29-h,108,58)}ctx.restore();ctx.globalAlpha=bright?1:.35;ctx.strokeStyle='#64706b55';ctx.lineWidth=1;ctx.stroke();ctx.strokeStyle='#080d10aa';for(let j=1;j<3;j++){ctx.beginPath();ctx.moveTo(s.x-54,s.y-h+j*16);ctx.lineTo(s.x,s.y+29-h+j*16);ctx.lineTo(s.x+54,s.y-h+j*16);ctx.stroke()}ctx.strokeStyle='#05090b88';for(let j=0;j<3;j++){let bx=s.x-40+(j%2)*18;ctx.beginPath();ctx.moveTo(bx,s.y-h+j*16+(bx-s.x+54)*.54);ctx.lineTo(bx,s.y-h+(j+1)*16+(bx-s.x+54)*.54);ctx.stroke()}ctx.globalAlpha=1}
function groundRing(x,y,r,color,width=2){let s=project(x,y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.ellipse(s.x,s.y,r*ISOX*1.42,r*ISOY*1.42,0,0,Math.PI*2);ctx.stroke()}
function spriteFrame(state,time){return{row:state==='attack'?2:state==='walk'?1:0,col:state==='attack'?Math.min(3,Math.floor(time/.85*4)):Math.floor(time*(state==='walk'?9:3))%4}}
function actorSprite(sheet,x,y,size,state,time,facing,alpha=1,flash=false){let s=project(x,y);ctx.save();ctx.translate(s.x,s.y);ctx.scale(facing,1);ctx.globalAlpha=alpha;ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(0,0,size*.23,size*.095,0,0,6.28);ctx.fill();if(sheet.complete&&sheet.naturalWidth){let f=spriteFrame(state,time),sw=sheet.naturalWidth/4,sh=sheet.naturalHeight/3;ctx.filter=flash?'brightness(1.8)':'none';ctx.drawImage(sheet,f.col*sw,f.row*sh,sw,sh,-size*.5,-size*.88,size,size)}ctx.restore()}
function drawObject(o,type){let s=project(o.x,o.y);if(!visibleAt(o.x,o.y))return;if(type==='altar'){groundRing(o.x,o.y,50,o.used?'#866a49':'#7c9ba8');ctx.fillStyle='#383b39';ctx.fillRect(s.x-15,s.y-25,30,27);ctx.fillStyle=o.used?'#706047':'#a2d9df';ctx.beginPath();ctx.moveTo(s.x,s.y-52);ctx.lineTo(s.x+9,s.y-34);ctx.lineTo(s.x,s.y-25);ctx.lineTo(s.x-9,s.y-34);ctx.closePath();ctx.fill();if(!o.used){let g=ctx.createRadialGradient(s.x,s.y-36,2,s.x,s.y-36,60);g.addColorStop(0,'#8dccda45');g.addColorStop(1,'#8dccda00');circle(s.x,s.y-36,60,g)}ctx.fillStyle='#cbd0bd';ctx.font='11px Georgia';ctx.textAlign='center';ctx.fillText(o.used?'解放済み':'F · 封印を解く',s.x,s.y-65)}else{ctx.fillStyle=o.opened?'#292723':'#655333';ctx.fillRect(s.x-19,s.y-19,38,23);ctx.strokeStyle='#a18b5c';ctx.strokeRect(s.x-19,s.y-19,38,23);ctx.fillStyle='#b39858';ctx.fillRect(s.x-3,s.y-15,6,15);if(!o.opened){ctx.fillStyle='#c6b58a';ctx.font='10px Georgia';ctx.textAlign='center';ctx.fillText('F · 古い宝箱',s.x,s.y-29)}}}
function drawWorldMap(large=false){let size=large?Math.min(W*.6,H*.52):155,scale=size/MW,x=large?(W-size)/2:24,y=large?H*.16:100;ctx.save();ctx.fillStyle=large?'#060b11ed':'#050a10a8';ctx.fillRect(x-10,y-10,size+20,size+35);ctx.strokeStyle='#726348';ctx.strokeRect(x-10,y-10,size+20,size+35);for(let gy=0;gy<MH;gy++)for(let gx=0;gx<MW;gx++){let i=cell(gx,gy);if(dungeon.seen[i]&&dungeon.tiles[i]){ctx.fillStyle=dungeon.visible[i]?'#8b8c78':'#424b4a';ctx.fillRect(x+gx*scale,y+gy*scale,Math.ceil(scale),Math.ceil(scale))}}for(let a of dungeon.altars){let g=gridPos(a.x,a.y);if(dungeon.seen[cell(g.x,g.y)])circle(x+g.x*scale,y+g.y*scale,large?5:2.5,a.used?'#9f865a':'#92dde1')}for(let chest of dungeon.chests){let c=gridPos(chest.x,chest.y);if(dungeon.seen[cell(c.x,c.y)]&&!chest.opened){ctx.fillStyle='#e3b75d';let r=large?3:2;ctx.fillRect(x+c.x*scale-r,y+c.y*scale-r,r*2,r*2)}}let throne=dungeon.rooms[8];if(dungeon.seen[cell(throne.cx,throne.cy)]){ctx.strokeStyle=portal?'#80dcc3':'#de756a';ctx.lineWidth=2;ctx.strokeRect(x+throne.cx*scale-4,y+throne.cy*scale-4,8,8)}let g=gridPos(p.x,p.y);circle(x+g.x*scale,y+g.y*scale,large?5:3,'#fce4a9');ctx.fillStyle='#b8aa86';ctx.font='10px Georgia';ctx.textAlign='left';ctx.fillText(large?'TAB · 地図を閉じる　金：宝箱　水色：封印　赤：玉座 / 緑：出口':'TAB · 探索地図',x,y+size+18);ctx.restore()}
function drawGroundEffects(){}
function selectGroundDrop(x,y,world){return drops.find(d=>dist(d,world)<40);}

function drawGroundDrops(){for(let d of drops)if(visibleAt(d.x,d.y)){let s=project(d.x,d.y);circle(s.x,s.y,4,d.item.color==='gold'?'#e5ba58':'#7eabce');ctx.fillStyle='#080c0ee8';ctx.fillRect(s.x-59,s.y-24,118,17);ctx.strokeStyle=d.item.color==='gold'?'#6f5b31':'#3c5060';ctx.strokeRect(s.x-59,s.y-24,118,17);ctx.fillStyle=d.item.color==='gold'?'#e5ba58':'#8cbce0';ctx.font='10px Georgia';ctx.textAlign='center';ctx.fillText(d.item.name,s.x,s.y-12)}}

function drawEffects(){ctx.save();ctx.globalCompositeOperation='lighter';for(let f of fx){let s=project(f.x,f.y);ctx.globalAlpha=clamp(f.life/f.max,0,1);if(f.arc!==undefined){ctx.strokeStyle=f.color;ctx.lineWidth=7;ctx.beginPath();for(let j=0;j<=20;j++){let a=f.arc-1+j*.1,t=project(f.x+Math.cos(a)*f.r,f.y+Math.sin(a)*f.r);j?ctx.lineTo(t.x,t.y):ctx.moveTo(t.x,t.y)}ctx.stroke()}else groundRing(f.x,f.y,f.r*(1-f.life/f.max*.5),f.color,2)}ctx.globalAlpha=1;for(let s of shots){if(s.art==='windBlade'){drawWindBlade(s);continue}if(s.art==='throwingKnife'){drawThrowingKnife(s);continue}if(s.art==='woodArrow'){drawWoodArrow(s);continue}let pos=project(s.x,s.y);let col=s.enemy?'#be79b6':s.tint||'#ffb45c';circle(pos.x,pos.y,6,col);ctx.globalAlpha=.4;circle(pos.x,pos.y,13,col);ctx.globalAlpha=1}for(let z of zonesFx){ctx.strokeStyle=z.kind==='bolt'?'#c2d7ff':'#9b78da';ctx.globalAlpha=Math.min(1,z.life*3);if(z.kind==='bolt'){ctx.lineWidth=2;let from=project(z.x,z.y),to=project(z.tx,z.ty);ctx.beginPath();ctx.moveTo(from.x,from.y-20);for(let j=1;j<=6;j++)ctx.lineTo(from.x+(to.x-from.x)*j/6+(j<6?Math.sin(j*43+clock*30)*12:0),from.y+(to.y-from.y)*j/6-20);ctx.stroke()}else{for(let j=0;j<3;j++)groundRing(z.x,z.y,z.r*(.5+j*.2),'#9b78da',2)}}for(let a of particles){let s=project(a.x,a.y);ctx.globalAlpha=Math.min(1,a.life*2);circle(s.x,s.y,1.8,a.color)}ctx.restore();for(let t of texts.slice(-80)){let s=project(t.x,t.y);ctx.save();ctx.globalAlpha=Math.min(1,t.life*5);ctx.fillStyle=t.c;ctx.font=t.crit?'800 21px sans-serif':'bold 16px sans-serif';ctx.textAlign='center';ctx.strokeStyle='#080d14';ctx.lineWidth=3;ctx.lineJoin='round';ctx.strokeText(t.s,s.x,s.y-30);ctx.fillText(t.s,s.x,s.y-30);ctx.restore()}}
function drawHud(){if(!p)return;$('hpFill').style.height=100*Math.max(0,p.hp)/maxhp()+'%';hudText($('hpText'),Math.max(0,Math.ceil(p.hp))+' / '+maxhp());$('mpFill').style.height=p.mp+'%';hudText($('mpText'),Math.floor(p.mp)+' / 100');$('xp').style.width=p.xp/(p.level*70)*100+'%';hudText($('stats'),'LEVEL '+p.level+'　 ·　 '+roomTitle+'　 ·　 '+p.gold+' G');hudText($('flasks'),p.flasks+' / 3');let buttons=document.querySelectorAll('.actions button');for(let i=0;i<2;i++){let b=skillBuild(p.bindings?.[i]),type=b?.type||'none';hudText(buttons[i+1].querySelector('strong'),b?GEM[type].name:'未装着');hudData(buttons[i+1],'skill',type);buttons[i+1].style.setProperty('--cool',b?Math.min(1,cd[i+1]/b.cool):0);hudText($('cd'+(i+1)),b?(cd[i+1]>.05?cd[i+1].toFixed(1)+' s':Math.ceil(b.cost)+' MANA'):'G で装着')}hudText($('cd3'),cd[3]>.05?cd[3].toFixed(1)+' s':'DASH');hudText($('objective'),portal?'奥の門から次の深度へ':bossSpawn?'黒冠の番人を倒す':seals===3?'黒冠の玉座へ向かう':'3つの封印を解く');hudText($('progress'),'封印 '+seals+' / 3　探索 '+dungeon.rooms.filter(r=>r.visited).length+' / 9');}
function terrainViewBounds(margin=180){let px=p?.x||0,py=p?.y||0;return {uMin:((-margin-W/2)/ISOX+px-py)/TILE,uMax:((W/2+margin)/ISOX+px-py)/TILE,vMin:((-margin-H/2)/ISOY+px+py)/TILE+18,vMax:((H/2+margin)/ISOY+px+py)/TILE+18};}
draw=()=>{ctx.fillStyle='#070b0e';ctx.fillRect(0,0,W,H);if(!started||!dungeon){if(terrain.complete&&terrain.naturalWidth){ctx.globalAlpha=.35;ctx.drawImage(terrain,0,0,W,H);ctx.globalAlpha=1}return}ctx.save();if(shake>0)ctx.translate(Math.sin(clock*140)*shake,Math.cos(clock*110)*shake*.5);let cachedVillageFloor=typeof drawVillageFloorLayer==='function'&&drawVillageFloorLayer();let walls=[],actors=[],view=terrainViewBounds();for(let gy=0;gy<MH;gy++)for(let gx=Math.max(0,Math.ceil(Math.max(gy+view.uMin,view.vMin-gy))-1),lastX=Math.min(MW-1,Math.floor(Math.min(gy+view.uMax,view.vMax-gy))+1);gx<=lastX;gx++){let screen=project((gx-9)*TILE,(gy-9)*TILE);if(screen.x<-180||screen.x>W+180||screen.y<-180||screen.y>H+180)continue;let id=cell(gx,gy);if(dungeon.seen[id]&&!cachedVillageFloor)floorTile(gx,gy);if(!isFloor(gx,gy)){let adjacent=false;for(let [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]])if(isFloor(gx+dx,gy+dy)&&dungeon.seen[cell(gx+dx,gy+dy)])adjacent=true;if(adjacent){if(typeof drawTerrainEdge==='function')drawTerrainEdge(gx,gy);let c=center(gx,gy);actors.push({depth:c.x+c.y,draw:()=>wall(gx,gy)})}}}drawGroundEffects();for(let c of corpses)if(visibleAt(c.x,c.y)){if(typeof drawEnemyRemains==='function')actors.push({depth:c.x+c.y-1,draw:()=>drawEnemyRemains(c)});else{let s=project(c.x,c.y);ctx.save();ctx.translate(s.x,s.y);ctx.scale(1,.3);ctx.rotate(.5);ctx.globalAlpha=Math.min(.4,c.life/4);if(enemySheet.complete&&enemySheet.naturalWidth)ctx.drawImage(enemySheet,0,0,enemySheet.naturalWidth/4,enemySheet.naturalHeight/3,-35,-25,70,70);ctx.restore()}}
if(moveGoal&&route.length)groundRing(moveGoal.x,moveGoal.y,12,'#d2b16a',1);for(let room of (p?.campaign?[]:dungeon.rooms))for(let side of [-1,1]){let t=center(room.cx+side*((room.w-3)/2),room.cy-(room.h-3)/2);if(visibleAt(t.x,t.y))actors.push({depth:t.x+t.y,draw:()=>drawTorch(t)})}for(let a of dungeon.altars)actors.push({depth:a.x+a.y,draw:()=>drawObject(a,'altar')});for(let c of dungeon.chests)actors.push({depth:c.x+c.y,draw:()=>drawObject(c,'chest')});for(let e of enemies)if(visibleAt(e.x,e.y)){if(e===attackTarget)groundRing(e.x,e.y,enemyHitRadius(e),'#c24839',2);if(e.state==='attack'&&!e.struck&&!e.attack?.final&&!e.attack?.bespoke)groundRing(e.x,e.y,e.kind?35:65,'#bf5d4277',2);actors.push({depth:e.x+e.y,draw:()=>{let size=enemyVisualSize(e);if(typeof drawRegionEnemy!=='function'||!drawRegionEnemy(e,size))actorSprite(enemySheet,e.x,e.y,size,e.state,e.state==='attack'?e.elapsed:e.anim,e.facing,1,e.flash>0);let s=project(e.x,e.y);ctx.fillStyle='#100d0e';ctx.fillRect(s.x-21,s.y-size*.8,42,4);ctx.fillStyle=e.boss||e.elite?'#b59459':'#954a3a';ctx.fillRect(s.x-21,s.y-size*.8,42*e.hp/e.max,4);drawEliteLabel(e,s,size);drawAilmentStatus(e,s,size);if(e.boss){ctx.fillStyle='#e1ca99';ctx.textAlign='center';ctx.font='12px Georgia';ctx.fillText(e.name||'黒冠の番人',s.x,s.y-size*.8-10)}}})}if(typeof addVillageActors==='function')addVillageActors(actors);if(typeof addCompanionActors==='function')addCompanionActors(actors);if(typeof addVillagePartyActors==='function')addVillagePartyActors(actors);actors.push({depth:p.x+p.y,draw:()=>drawPlayerActor()});actors.sort((a,b)=>a.depth-b.depth).forEach(a=>a.draw());
drawGroundDrops();if(portal&&dungeon.exit){let e=dungeon.exit,s=project(e.x,e.y);groundRing(e.x,e.y,65,'#71cebd',3);ctx.strokeStyle='#9bdac9';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(s.x,s.y-43,26+Math.sin(clock*3)*3,50,0,0,6.28);ctx.stroke();ctx.fillStyle='#c2e0d6';ctx.font='12px Georgia';ctx.textAlign='center';ctx.fillText('F · 次の深度',s.x,s.y-106)}drawEffects();ctx.restore();let v=ctx.createRadialGradient(W/2,H/2,H*.2,W/2,H/2,Math.max(W,H)*.68);v.addColorStop(0,'#0000');v.addColorStop(1,'#020508db');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);drawWorldMap(false);if(mapOpen)drawWorldMap(true);drawHud()};
const expeditionPanel=panel;panel=kind=>{route=[];leftDown=false;rightDown=false;attackTarget=null;expeditionPanel(kind);if(kind==='help')$('card').innerHTML+='<hr><h3>探索と操作</h3><p>左クリック：移動・敵を指定して追跡攻撃。Shift＋左クリック：その場で攻撃。右クリック / Q：第1スキル（長押し可）。E：第2スキル。WASD：画面方向へ移動。Space：壁で止まる瞬歩。Tab：探索済み地図。F：宝箱・封印・拾う・出口。<br>書庫、貯蔵庫、祭室の敵を倒して3つの封印を解き、最奥の番人へ進んでください。</p>'};
hudText(document.querySelector('.hint'),'左クリック 移動・攻撃 · SHIFT その場攻撃 · 右クリック スキル · WASD 移動 · TAB 地図 · F 調べる');
hudText(document.querySelector('.actions button kbd'),'SHIFT + 左クリック');

function drawTorch(t){let s=project(t.x,t.y),flicker=Math.sin(clock*15+t.x)*2;ctx.save();ctx.globalCompositeOperation='lighter';let glow=ctx.createRadialGradient(s.x,s.y-32,2,s.x,s.y-32,105);glow.addColorStop(0,'#d79a3542');glow.addColorStop(1,'#bc651100');circle(s.x,s.y-32,105,glow);ctx.restore();ctx.fillStyle='#181b19';ctx.fillRect(s.x-5,s.y-27,10,29);ctx.fillStyle='#76603b';ctx.fillRect(s.x-12,s.y-30,24,7);ctx.fillStyle='#d9842e';ctx.beginPath();ctx.moveTo(s.x-8,s.y-29);ctx.quadraticCurveTo(s.x-12,s.y-42,s.x+flicker,s.y-54);ctx.quadraticCurveTo(s.x+12,s.y-40,s.x+8,s.y-29);ctx.closePath();ctx.fill();circle(s.x,s.y-33,4,'#ffe6a1')}





function drawPlayerActor(){actorSprite(heroSheet,p.x,p.y,100,playerAction?'attack':playerMoving?'walk':'idle',playerAction?playerAction.elapsed/playerAction.duration*.85:playerAnim,face,p.inv>0?.75:1);}
